INSERT INTO courses (course_code, course_name, description, status) VALUES
('CS101', 'Introduction to Computer Science', 'Fundamental concepts of computer science including programming basics, algorithms, and data structures.', 'open'),
('CS201', 'Database Systems', 'Comprehensive study of database design, SQL, normalization, and database management systems.', 'open'),
('CS301', 'Web Development', 'Modern web development using HTML, CSS, JavaScript, PHP, and frameworks.', 'open'),
('CS302', 'Software Engineering', 'Software development lifecycle, project management, and best practices in software engineering.', 'open'),
('CS401', 'Machine Learning Fundamentals', 'Introduction to machine learning algorithms, neural networks, and data science.', 'open'),
('CS402', 'Cybersecurity Basics', 'Fundamentals of cybersecurity, network security, encryption, and ethical hacking.', 'open'),
('CS403', 'Mobile Application Development', 'Development of mobile applications for iOS and Android platforms.', 'open'),
('MATH101', 'Discrete Mathematics', 'Mathematical foundations for computer science including logic, sets, and graph theory.', 'open'),
('MATH201', 'Linear Algebra', 'Vector spaces, matrices, eigenvalues, and applications in computer science.', 'open'),
('ENG101', 'Technical Writing', 'Professional writing skills for technical documentation and communication.', 'open');

INSERT INTO course_lecturers (course_id, lecturer_id)
SELECT 
    (SELECT course_id FROM courses WHERE course_code = 'CS101') AS course_id,
    (SELECT user_id FROM users WHERE email = 'norazlina.ahmad@ez2learn.edu.my' AND role = 'lecturer') AS lecturer_id
WHERE EXISTS (SELECT 1 FROM courses WHERE course_code = 'CS101')
  AND EXISTS (SELECT 1 FROM users WHERE email = 'norazlina.ahmad@ez2learn.edu.my' AND role = 'lecturer');

