INSERT INTO enrollments (course_id, student_id)
SELECT 
    (SELECT course_id FROM courses WHERE course_code = 'CS101') AS course_id,
    (SELECT user_id FROM users WHERE email = 'aisyah.mohdali@ez2learn.edu.my' AND role = 'student') AS student_id
WHERE EXISTS (SELECT 1 FROM courses WHERE course_code = 'CS101')
  AND EXISTS (SELECT 1 FROM users WHERE email = 'aisyah.mohdali@ez2learn.edu.my' AND role = 'student')
  AND NOT EXISTS (SELECT 1 FROM enrollments WHERE course_id = (SELECT course_id FROM courses WHERE course_code = 'CS101') AND student_id = (SELECT user_id FROM users WHERE email = 'aisyah.mohdali@ez2learn.edu.my' AND role = 'student'));

